using UnityEngine;using UnityEditor;using RoadGunner.Editor;public static class FaceGreenwoodDoor{public static string Main(){var l=RoadGunnerLevelAuthoring.Current;var t=l.obstaclesRoot.Find("G · Northeast camp and sealed entrance").Find("Sealed Cliff Door");t.rotation=Quaternion.Euler(0,90,0);PrefabUtility.RecordPrefabInstancePropertyModifications(t);var future=l.decorationRoot.Find("Future biomes · visible beyond locked gates");if(!future.Find("Cactus at west gate")){var cactus=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(AstraZone01Builder.Root+"/Prefabs/Cactus.prefab"),future);cactus.name="Cactus at west gate";cactus.transform.SetPositionAndRotation(AstraZone01Builder.World(-52.5f,24),Quaternion.Euler(0,60,0));cactus.transform.localScale=Vector3.one*.7f;PrefabUtility.RecordPrefabInstancePropertyModifications(cactus.transform);}RoadGunnerLevelAuthoring.Save(l);return "Sealed door faces screen southwest; cactus frames the closed orange-biome approach";}}